-- Demo mock exam: 65 timed questions across the VPC and S3 modules.
-- GENERATED by scripts/generate_mock_exam.py. Edit that file, not this one.
-- Original questions written for SkillPulse; not copied from any exam or course.
-- 33 Networking and VPC questions, 32 Storage and S3 questions.
-- Idempotent: safe to run more than once.
BEGIN;

ON CONFLICT (id) DO NOTHING;

VALUES ('63000000-0000-0000-0000-000000000004', '40000000-0000-0000-0000-000000000001', 'Mock Exam: VPC and S3', 'mock_exam', 65, 130, 70, 3, 'published', NOW())
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (assessment_id, question_id) DO NOTHING;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM assessments
        WHERE id = '63000000-0000-0000-0000-000000000004'
          AND assessment_type = 'mock_exam'
          AND question_count = 65
          AND time_limit_minutes = 130
          AND pass_percentage = 70
          AND status = 'published'
    ) THEN
        RAISE EXCEPTION 'Mock exam configuration differs from the demo definition.';
    END IF;

    IF (
        SELECT COUNT(*)
        FROM assessment_questions AS aq
        JOIN questions AS q ON q.id = aq.question_id
        WHERE aq.assessment_id = '63000000-0000-0000-0000-000000000004'
          AND q.status = 'published'
          AND q.correct_answer_json <@ q.options_json
    ) <> 65 THEN
        RAISE EXCEPTION 'Mock exam must link 65 published questions with valid answers.';
    END IF;
END
$$;

COMMIT;

SELECT a.title, a.assessment_type, a.question_count, a.time_limit_minutes, a.pass_percentage,
       COUNT(*) FILTER (WHERE q.topic_id = '41000000-0000-0000-0000-000000000001') AS vpc_questions,
       COUNT(*) FILTER (WHERE q.topic_id = '41000000-0000-0000-0000-000000000002') AS s3_questions
FROM assessments AS a
JOIN assessment_questions AS aq ON aq.assessment_id = a.id
JOIN questions AS q ON q.id = aq.question_id
WHERE a.id = '63000000-0000-0000-0000-000000000004'
GROUP BY a.id;
