INSERT INTO questions (id, topic_id, question_text, question_type, options_json, correct_answer_json, explanation, difficulty, verified_source_id, status)
VALUES
    ('62000000-0000-0000-0003-000000000001', '41000000-0000-0000-0000-000000000001', 'A company''s on-premises network uses 10.0.0.0/16. It is creating a VPC that will later connect to the office over a VPN. Which VPC CIDR block avoids an overlap?', 'single_choice', '["10.0.0.0/8", "10.0.128.0/17", "172.16.0.0/16", "10.0.5.0/24"]', '["172.16.0.0/16"]', '172.16.0.0/16 is a private range that does not overlap 10.0.0.0/16. The other three ranges all include addresses inside 10.0.0.0/16, which would break routing between the networks.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000002', '41000000-0000-0000-0000-000000000001', 'What is the largest IPv4 CIDR block you can assign to a VPC?', 'single_choice', '["/28", "/16", "/24", "/8"]', '["/16"]', 'A VPC IPv4 CIDR block can be between /16 (65,536 addresses) and /28 (16 addresses). /16 is the largest.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000003', '41000000-0000-0000-0000-000000000001', 'Which statement about subnets in Amazon VPC is correct?', 'single_choice', '["A subnet can span every Availability Zone in a Region.", "A subnet can span two Regions.", "Each subnet exists in exactly one Availability Zone.", "A subnet is automatically shared with every VPC in the account."]', '["Each subnet exists in exactly one Availability Zone."]', 'A subnet always sits in a single Availability Zone. For high availability you create subnets in several AZs.', 1, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000004', '41000000-0000-0000-0000-000000000001', 'Web servers run in an Auto Scaling group and must keep working if one Availability Zone fails. What is the minimum subnet design?', 'single_choice', '["Subnets in two or more Availability Zones, used by the Auto Scaling group", "Two subnets in the same Availability Zone, with the group using both of them", "One large subnet in a single Availability Zone, with a bigger instance type", "One subnet in each Region, connected with VPC peering"]', '["Subnets in two or more Availability Zones, used by the Auto Scaling group"]', 'Because a subnet lives in one AZ, surviving an AZ failure needs subnets in at least two AZs and an Auto Scaling group that launches instances across them.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000005', '41000000-0000-0000-0000-000000000001', 'Instances in a private subnet cannot download updates. Their route table sends 0.0.0.0/0 to a NAT gateway, and the NAT gateway is in a public subnet. What is the most likely missing piece?', 'single_choice', '["The private instances'' security group must allow inbound traffic from the internet.", "The private instances need public IPv4 addresses.", "The public subnet''s route table has no 0.0.0.0/0 route to an internet gateway.", "The NAT gateway must be moved into the private subnet."]', '["The public subnet''s route table has no 0.0.0.0/0 route to an internet gateway."]', 'A NAT gateway forwards traffic to the internet through the internet gateway, using the route table of the subnet it sits in. Without that route, outbound traffic has nowhere to go. Private instances do not need public IPs or inbound rules for this.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000006', '41000000-0000-0000-0000-000000000001', 'Which statement about a NAT gateway is correct?', 'single_choice', '["It lets internet users connect directly to instances in private subnets.", "It must be placed in a private subnet, next to the instances that use it.", "It allows outbound connections from private instances, but not inbound ones from the internet.", "You attach a security group to the NAT gateway to control which instances can use it."]', '["It allows outbound connections from private instances, but not inbound ones from the internet."]', 'A NAT gateway only allows connections that start inside the VPC. You cannot attach security groups to it (network ACLs still apply), and it must be in a public subnet.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000007', '41000000-0000-0000-0000-000000000001', 'Instances that use IPv6 need outbound-only internet access over IPv6, with no inbound connections from the internet. What should you use?', 'single_choice', '["A virtual private gateway", "A NAT gateway", "A VPC peering connection", "An egress-only internet gateway"]', '["An egress-only internet gateway"]', 'An egress-only internet gateway is the IPv6 equivalent of NAT for outbound-only access. NAT gateways are for IPv4 traffic.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000008', '41000000-0000-0000-0000-000000000001', 'A security group has one inbound rule: allow TCP 22 from 203.0.113.10/32. What happens to an SSH connection attempt from 198.51.100.5?', 'single_choice', '["It is denied, because traffic that no rule allows is denied.", "It is allowed, because the outbound rules allow all traffic.", "It is allowed if the network ACL allows it.", "It is denied only if a deny rule for 198.51.100.5 is added."]', '["It is denied, because traffic that no rule allows is denied."]', 'Security groups only have allow rules. Anything not explicitly allowed is denied, so no deny rule is needed.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000009', '41000000-0000-0000-0000-000000000001', 'A network ACL has rule 90: DENY all traffic from 198.51.100.0/24, and rule 100: ALLOW TCP 443 from 0.0.0.0/0. A client at 198.51.100.7 connects on port 443. What happens?', 'single_choice', '["Only the security group decides; network ACL rule order does not matter.", "It is denied, because rule 90 is checked first and matches.", "It is allowed, because allow rules always win.", "It is allowed, because rule 100 is the higher number."]', '["It is denied, because rule 90 is checked first and matches."]', 'Network ACL rules are checked in number order, lowest first, and the first matching rule is applied. Rule 90 matches the client, so the traffic is denied.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000010', '41000000-0000-0000-0000-000000000001', 'Which TWO statements about security groups are correct? (Choose two.)', 'multiple_choice', '["They support explicit deny rules for blocking single IP addresses.", "They are stateful: replies to allowed traffic are allowed automatically.", "They apply to every instance in a subnet automatically.", "A rule can use another security group as its source.", "Their rules are checked in number order, lowest number first."]', '["They are stateful: replies to allowed traffic are allowed automatically.", "A rule can use another security group as its source."]', 'Security groups are stateful, allow-only and attached to network interfaces. They can reference other security groups. Numbered rules and subnet-wide rules describe network ACLs.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000011', '41000000-0000-0000-0000-000000000001', 'Administrators need shell access to EC2 instances in private subnets without opening port 22 to the internet and without running a bastion host. What should they use?', 'single_choice', '["An Elastic IP address on each instance", "A NAT gateway with port forwarding", "AWS Systems Manager Session Manager", "A VPC peering connection to the administrators'' laptops"]', '["AWS Systems Manager Session Manager"]', 'Session Manager connects through the SSM Agent over HTTPS, so no inbound ports, bastion hosts or SSH keys are needed, and sessions can be logged.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000012', '41000000-0000-0000-0000-000000000001', 'Gateway VPC endpoints are available for which TWO services? (Choose two.)', 'multiple_choice', '["Amazon SQS", "Amazon EC2 API", "Amazon DynamoDB", "AWS Systems Manager", "Amazon S3"]', '["Amazon S3", "Amazon DynamoDB"]', 'Gateway endpoints exist only for Amazon S3 and DynamoDB. Most other services use interface endpoints (AWS PrivateLink).', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000013', '41000000-0000-0000-0000-000000000001', 'Instances in private subnets must call the Amazon SQS API without using the internet or a NAT gateway. What should you create?', 'single_choice', '["An egress-only internet gateway for the private subnets", "An interface VPC endpoint (AWS PrivateLink) for Amazon SQS", "A gateway VPC endpoint for Amazon SQS, added to the route table", "An internet gateway attached to the VPC"]', '["An interface VPC endpoint (AWS PrivateLink) for Amazon SQS"]', 'SQS is reached privately through an interface endpoint, which places network interfaces in your subnets. Gateway endpoints only support S3 and DynamoDB.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000014', '41000000-0000-0000-0000-000000000001', 'An interface endpoint for Amazon SQS was created, but instances still resolve the public SQS address and fail, because there is no NAT gateway. What is the most likely fix?', 'single_choice', '["Add a network ACL rule that denies the public SQS address range.", "Attach an internet gateway so the public SQS address can be reached directly.", "Turn on private DNS for the endpoint, with DNS support and hostnames on in the VPC.", "Create a VPC peering connection to the VPC that hosts the SQS service."]', '["Turn on private DNS for the endpoint, with DNS support and hostnames on in the VPC."]', 'With private DNS enabled, the normal SQS hostname resolves to the endpoint''s private IP addresses inside the VPC. This needs the VPC''s DNS support and DNS hostnames settings.', 4, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000015', '41000000-0000-0000-0000-000000000001', 'A company runs a service behind a Network Load Balancer and wants to offer it privately to hundreds of customer VPCs. Customers'' CIDR ranges may overlap, and the company must not expose its whole network. What is the best solution?', 'single_choice', '["Expose the service on the internet with an IP allow-list", "Publish the service as an AWS PrivateLink endpoint service", "Attach every customer VPC to one transit gateway", "Create a VPC peering connection with each customer"]', '["Publish the service as an AWS PrivateLink endpoint service"]', 'PrivateLink exposes only one service, not whole networks, and works even when CIDR ranges overlap. Peering and Transit Gateway connect networks and need non-overlapping ranges.', 4, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000016', '41000000-0000-0000-0000-000000000001', 'Two VPCs both use the CIDR block 10.0.0.0/16. Can you connect them with VPC peering?', 'single_choice', '["Yes, after adding routes to both route tables.", "No. Peered VPCs must not have overlapping CIDR blocks.", "Yes, if the VPCs are in different Regions.", "Yes, but traffic can only flow in one direction."]', '["No. Peered VPCs must not have overlapping CIDR blocks."]', 'VPC peering does not support overlapping CIDR blocks. Plan non-overlapping address ranges before you need to connect networks.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000017', '41000000-0000-0000-0000-000000000001', 'A VPC peering connection was created and accepted, but instances in the two VPCs still cannot talk to each other. Which TWO things are most likely missing? (Choose two.)', 'multiple_choice', '["An internet gateway attached to each VPC so the peered traffic can be routed", "A NAT gateway in each VPC to translate addresses between the two networks", "Security group rules that allow traffic from the peer VPC", "Routes to the peer VPC''s CIDR through the peering connection, on both sides", "An AWS Direct Connect connection between the two VPCs'' Regions"]', '["Routes to the peer VPC''s CIDR through the peering connection, on both sides", "Security group rules that allow traffic from the peer VPC"]', 'Peering needs routes on both sides and security group rules that allow the traffic. Peered traffic never uses internet gateways or NAT gateways.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000018', '41000000-0000-0000-0000-000000000001', 'A company has three VPCs and needs private connectivity between only two of them, at the lowest cost. What should it use?', 'single_choice', '["AWS Transit Gateway", "AWS Direct Connect", "A VPC peering connection", "An AWS Site-to-Site VPN between the VPCs"]', '["A VPC peering connection"]', 'VPC peering has no hourly charge, only data transfer, and is simplest for a single pair. Transit Gateway adds per-attachment hourly charges and is better for many VPCs.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000019', '41000000-0000-0000-0000-000000000001', 'A branch office needs an encrypted connection to a VPC by tomorrow, using its existing internet link. What is the best option?', 'single_choice', '["AWS Direct Connect", "A gateway VPC endpoint", "AWS Site-to-Site VPN", "VPC peering"]', '["AWS Site-to-Site VPN"]', 'A Site-to-Site VPN can be set up quickly over the internet and is encrypted with IPsec. Direct Connect is a physical connection that takes much longer to provision.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000020', '41000000-0000-0000-0000-000000000001', 'A company sends critical traffic over a single AWS Direct Connect connection. What is the lowest-cost way to add a backup path?', 'single_choice', '["Add an AWS Site-to-Site VPN as a backup connection", "Create a VPC peering connection to another Region", "Add a NAT gateway", "Increase the bandwidth of the Direct Connect connection"]', '["Add an AWS Site-to-Site VPN as a backup connection"]', 'A Site-to-Site VPN over the internet is a common low-cost backup for Direct Connect. More bandwidth does not remove the single point of failure.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000021', '41000000-0000-0000-0000-000000000001', 'Traffic over AWS Direct Connect is not encrypted by default, but a company''s policy requires encryption in transit. What can it do?', 'single_choice', '["Turn on default encryption for its S3 buckets", "Run an IPsec VPN connection over the Direct Connect connection", "Add network ACL rules to the Direct Connect subnets", "Nothing, because Direct Connect encrypts all traffic automatically"]', '["Run an IPsec VPN connection over the Direct Connect connection"]', 'Direct Connect is a private connection but not encrypted by default. Running a VPN over it (or using MACsec where supported) adds encryption in transit.', 4, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000022', '41000000-0000-0000-0000-000000000001', 'A team needs to see which source IP addresses are being rejected when they try to connect to an instance. Which feature should they use?', 'single_choice', '["AWS Config", "AWS Trusted Advisor", "AWS CloudTrail", "VPC Flow Logs"]', '["VPC Flow Logs"]', 'VPC Flow Logs record IP traffic to and from network interfaces, including whether it was accepted or rejected. CloudTrail records API calls, not network traffic.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000023', '41000000-0000-0000-0000-000000000001', 'Which statement about VPC Flow Logs is correct?', 'single_choice', '["They record traffic details such as IPs, ports and ACCEPT or REJECT, not packet contents.", "They can only be turned on for public subnets that use an internet gateway.", "They record full packet contents so you can inspect application data later.", "They can block traffic that matches a rule, in the same way as a network firewall."]', '["They record traffic details such as IPs, ports and ACCEPT or REJECT, not packet contents."]', 'Flow logs capture information about traffic, not payloads, and they do not affect traffic. They can be enabled for a VPC, a subnet or a network interface.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000024', '41000000-0000-0000-0000-000000000001', 'A server needs a fixed public IPv4 address that stays the same when the instance is stopped and started. What should you use?', 'single_choice', '["A NAT gateway", "A private IPv4 address", "An Elastic IP address", "The auto-assigned public IPv4 address"]', '["An Elastic IP address"]', 'An auto-assigned public IP changes after a stop and start. An Elastic IP address stays allocated to your account until you release it.', 1, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000025', '41000000-0000-0000-0000-000000000001', 'An internet-facing Application Load Balancer sends traffic to EC2 instances in private subnets. Where should the load balancer''s subnets be?', 'single_choice', '["In public subnets in at least two Availability Zones", "In any subnet, because load balancers do not use route tables", "In one public subnet only, because the load balancer scales automatically", "In the same private subnets as the instances, so traffic stays private"]', '["In public subnets in at least two Availability Zones"]', 'An internet-facing load balancer needs public subnets so clients can reach it, and needs at least two AZs. The targets can stay in private subnets.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000026', '41000000-0000-0000-0000-000000000001', 'Which statement about the default VPC is correct?', 'single_choice', '["It has private subnets only, and you must attach an internet gateway yourself.", "It has a public subnet in each AZ and an internet gateway already attached.", "It cannot be used to launch instances; it only holds default security groups.", "It has no subnets until you create them in each Availability Zone."]', '["It has a public subnet in each AZ and an internet gateway already attached."]', 'The default VPC is ready to use: each AZ has a default subnet with a route to the attached internet gateway.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000027', '41000000-0000-0000-0000-000000000001', 'Instances in a custom VPC must receive public DNS hostnames. Which TWO VPC settings must be enabled? (Choose two.)', 'multiple_choice', '["DNS resolution (DNS support)", "A VPC peering connection", "A NAT gateway", "VPC Flow Logs", "DNS hostnames"]', '["DNS hostnames", "DNS resolution (DNS support)"]', 'Both DNS resolution and DNS hostnames must be turned on for instances with public IP addresses to get public DNS names.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000028', '41000000-0000-0000-0000-000000000001', 'A route table contains: 10.0.0.0/16 local; 10.1.0.0/16 to a peering connection; 0.0.0.0/0 to an internet gateway. Where is traffic to 10.1.5.9 sent?', 'single_choice', '["To the internet gateway, because the 0.0.0.0/0 route matches every destination", "To the local route", "It is dropped, because two routes match", "To the peering connection, because the most specific matching route is used"]', '["To the peering connection, because the most specific matching route is used"]', 'Route tables use the longest prefix match. 10.1.0.0/16 is more specific than 0.0.0.0/0, so the peering connection is used.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000029', '41000000-0000-0000-0000-000000000001', 'Which statement about the local route in a VPC route table is correct?', 'single_choice', '["It sends traffic between subnets through the internet gateway.", "It lets all subnets in the VPC reach each other, and it cannot be deleted.", "You must add it to the route table manually after creating each subnet.", "It only covers public subnets that have a route to an internet gateway."]', '["It lets all subnets in the VPC reach each other, and it cannot be deleted."]', 'Every route table has a local route for the VPC''s CIDR, so subnets can always reach each other. Use security groups and network ACLs to limit that traffic.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000030', '41000000-0000-0000-0000-000000000001', 'A new subnet is created and not explicitly associated with a route table. Which route table does it use?', 'single_choice', '["The VPC''s main route table", "None, so no traffic can leave the subnet", "A new, empty route table", "The default VPC''s route table"]', '["The VPC''s main route table"]', 'Subnets without an explicit association use the main route table. Many teams keep the main table private and associate public subnets explicitly.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000031', '41000000-0000-0000-0000-000000000001', 'A company wants stateful inspection of all traffic entering and leaving its VPCs, including filtering by domain name. Which service should it use?', 'single_choice', '["VPC Flow Logs", "Security groups only", "AWS Network Firewall", "Amazon Route 53 health checks"]', '["AWS Network Firewall"]', 'AWS Network Firewall is a managed firewall that supports stateful rules and domain filtering. Flow logs only record traffic, and security groups cannot filter by domain.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000032', '41000000-0000-0000-0000-000000000001', 'Internal services need DNS names that only resolve inside selected VPCs. What should you create?', 'single_choice', '["A public hosted zone with records that only point to private IP addresses", "An Amazon CloudFront distribution in front of each service", "An Elastic IP address for each service, with a DNS record for each", "An Amazon Route 53 private hosted zone associated with those VPCs"]', '["An Amazon Route 53 private hosted zone associated with those VPCs"]', 'A private hosted zone answers DNS queries only from the VPCs you associate with it.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000033', '41000000-0000-0000-0000-000000000001', 'A security group allows inbound HTTP (port 80) from anywhere, but the subnet''s network ACL denies inbound port 80 from 0.0.0.0/0. What happens to HTTP requests from the internet?', 'single_choice', '["They are blocked, because both the network ACL and the security group must allow the traffic.", "They are allowed, because the security group''s allow rule overrides the network ACL.", "They are allowed, because security groups are stateful and remember the request.", "It depends only on the route table of the subnet."]', '["They are blocked, because both the network ACL and the security group must allow the traffic."]', 'Traffic must pass both layers. The network ACL is checked at the subnet boundary first, so its deny blocks the request before it reaches the instance.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000034', '41000000-0000-0000-0000-000000000002', 'Which statement about S3 bucket names is correct?', 'single_choice', '["Bucket names must be unique across all AWS accounts.", "Bucket names only need to be unique within your account.", "Bucket names can contain spaces and capital letters.", "Bucket names only need to be unique within a Region."]', '["Bucket names must be unique across all AWS accounts."]', 'Bucket names share one global namespace, even though each bucket lives in a single Region.', 1, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000035', '41000000-0000-0000-0000-000000000002', 'What is the largest size of a single object in Amazon S3?', 'single_choice', '["160 GB", "5 TB", "5 GB", "There is no limit"]', '["5 TB"]', 'An object can be up to 5 TB. A single PUT request can upload up to 5 GB; larger objects need multipart upload.', 1, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000036', '41000000-0000-0000-0000-000000000002', 'A 20 GB file must be uploaded to S3 quickly, and the upload must be able to continue if the network drops. What should you use?', 'single_choice', '["S3 Object Lock", "S3 Select", "A single PUT request", "Multipart upload"]', '["Multipart upload"]', 'Multipart upload sends parts in parallel and lets you retry only failed parts. A single PUT is limited to 5 GB.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000037', '41000000-0000-0000-0000-000000000002', 'An application writes a new object to S3 and immediately reads it. What does the read return?', 'single_choice', '["Nothing until the bucket''s index is rebuilt overnight", "The new object, because S3 is strongly consistent for reads after writes", "A 404 error until the object has been copied to every Availability Zone", "Possibly an older version for a few minutes after the write"]', '["The new object, because S3 is strongly consistent for reads after writes"]', 'S3 is strongly consistent: once a write succeeds, all following reads return the new data.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000038', '41000000-0000-0000-0000-000000000002', 'How is S3 Standard designed to protect your data?', 'single_choice', '["For 11 nines of durability, by storing data across several Availability Zones", "For 99.9% durability, by keeping two copies in one data centre", "By storing every object on one server in a single Availability Zone", "Durability depends on how many buckets you spread the data across"]', '["For 11 nines of durability, by storing data across several Availability Zones"]', 'S3 Standard keeps data across at least three AZs and is designed for 11 nines of durability.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000039', '41000000-0000-0000-0000-000000000002', 'All requests to a bucket must use HTTPS. How do you enforce this?', 'single_choice', '["Add a bucket policy that denies requests where aws:SecureTransport is false", "Use SSE-S3 encryption, which also encrypts every request in transit", "Turn on versioning so every request is recorded with a version ID", "Turn on Block Public Access for the bucket and for the whole account"]', '["Add a bucket policy that denies requests where aws:SecureTransport is false"]', 'The aws:SecureTransport condition key is false for plain HTTP requests, so an explicit deny on that condition blocks them. Encryption at rest does not control the transport.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000040', '41000000-0000-0000-0000-000000000002', 'An IAM role in account B must read objects in a bucket owned by account A. Which TWO are required? (Choose two.)', 'multiple_choice', '["Making the bucket public so that account B can read it without a policy", "Turning off Block Public Access on the bucket in account A", "An IAM policy on the role in account B that allows s3:GetObject on the bucket", "Turning on versioning so account B can read the objects'' versions", "A bucket policy in account A that allows the role from account B"]', '["A bucket policy in account A that allows the role from account B", "An IAM policy on the role in account B that allows s3:GetObject on the bucket"]', 'Cross-account access needs permission on both sides: the bucket policy trusts the other account''s role, and the role''s own policy allows the action.', 4, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000041', '41000000-0000-0000-0000-000000000002', 'Objects uploaded by another account are owned by that uploader, so the bucket owner cannot manage access to them. What is the recommended fix?', 'single_choice', '["Set Object Ownership to ''Bucket owner enforced'', which turns off ACLs", "Turn ACLs back on and grant the bucket owner full control on each upload", "Turn off default encryption so the bucket owner can open the objects", "Make the uploaded objects public so the bucket owner can read them"]', '["Set Object Ownership to ''Bucket owner enforced'', which turns off ACLs"]', 'With ''Bucket owner enforced'', the bucket owner owns every object and access is controlled only by policies. This is the default for new buckets.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000042', '41000000-0000-0000-0000-000000000002', 'A Lambda function only needs to read objects under the reports/ prefix of one bucket. Which permission follows least privilege?', 'single_choice', '["Allow s3:GetObject on arn:aws:s3:::bucket-name/reports/*", "Allow s3:GetObject on every bucket in the account", "Allow s3:* on all resources", "Attach the AmazonS3FullAccess managed policy"]', '["Allow s3:GetObject on arn:aws:s3:::bucket-name/reports/*"]', 'Least privilege means only the needed action (GetObject) on only the needed resources (that prefix in that bucket).', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000043', '41000000-0000-0000-0000-000000000002', 'Users of a mobile app must upload photos directly to S3 for a short time, without having AWS credentials. What is the best approach?', 'single_choice', '["Allow public writes on the bucket for the app''s users", "Put a long-term access key inside the app", "Turn on static website hosting for the bucket", "The backend generates presigned URLs for uploads"]', '["The backend generates presigned URLs for uploads"]', 'A presigned URL lets someone perform one specific action until it expires, using the backend''s permissions. Public write access and embedded keys are serious security risks.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000044', '41000000-0000-0000-0000-000000000002', 'Versioning is on, and storage costs keep rising because old versions build up. What is the best fix?', 'single_choice', '["Add a lifecycle rule that expires noncurrent versions after some days", "Suspend versioning, which deletes the old versions automatically", "Turn versioning off completely and remove the bucket''s history", "Turn on S3 Transfer Acceleration to move old versions faster"]', '["Add a lifecycle rule that expires noncurrent versions after some days"]', 'Lifecycle rules can expire noncurrent versions automatically. Suspending versioning does not delete existing versions, and versioning cannot be turned off once enabled.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000045', '41000000-0000-0000-0000-000000000002', 'What happens when you suspend versioning on a bucket?', 'single_choice', '["All earlier versions are deleted to save storage.", "All objects become locked until versioning is resumed.", "Existing versions are kept, and new objects get a null version ID.", "Old versions are kept, but versioning can never be turned on again."]', '["Existing versions are kept, and new objects get a null version ID."]', 'Suspending stops creating new versions but keeps every existing version. You can turn versioning on again later.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000046', '41000000-0000-0000-0000-000000000002', 'A company wants an extra safeguard so that permanently deleting an object version requires a multi-factor authentication code. What should it use?', 'single_choice', '["Block Public Access on the bucket and the account", "Requester Pays on the bucket", "MFA Delete on the versioned bucket", "SSE-KMS encryption with a customer managed key"]', '["MFA Delete on the versioned bucket"]', 'MFA Delete requires an MFA code to permanently delete a version or change the bucket''s versioning state.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000047', '41000000-0000-0000-0000-000000000002', 'Records must be protected so that no user, including the root user, can delete them or shorten the retention period. Which S3 Object Lock setting meets this?', 'single_choice', '["Compliance mode", "Versioning without Object Lock", "Governance mode", "A lifecycle expiration rule"]', '["Compliance mode"]', 'In compliance mode nobody can delete the object or shorten its retention until it ends. Governance mode lets users with special permission override it.', 4, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000048', '41000000-0000-0000-0000-000000000002', 'Lawyers need a specific object kept until a court case ends, but nobody knows when that will be. Which feature fits best?', 'single_choice', '["An Object Lock legal hold", "MFA Delete", "A lifecycle rule", "Compliance-mode retention for 10 years"]', '["An Object Lock legal hold"]', 'A legal hold protects an object with no end date until someone with permission removes it. Retention periods need a fixed date.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000049', '41000000-0000-0000-0000-000000000002', 'Cross-Region Replication was set up today, but objects that already existed in the bucket were not copied. How can they be replicated?', 'single_choice', '["Add a lifecycle transition rule", "Wait, because replication copies existing objects within 24 hours", "Turn versioning off and on again", "Use S3 Batch Replication"]', '["Use S3 Batch Replication"]', 'Replication rules only apply to new objects. S3 Batch Replication copies objects that existed before the rule was added.', 4, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000050', '41000000-0000-0000-0000-000000000002', 'Log files must also be copied to a bucket in another account in the same Region, for a separate security team. What should you use?', 'single_choice', '["S3 Transfer Acceleration", "S3 Cross-Region Replication", "S3 Glacier Deep Archive", "S3 Same-Region Replication"]', '["S3 Same-Region Replication"]', 'Same-Region Replication copies objects to another bucket in the same Region, including one in a different account.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000051', '41000000-0000-0000-0000-000000000002', 'A company needs an SLA that 99.99% of new objects are replicated to another Region within 15 minutes. What should it turn on?', 'single_choice', '["Multipart upload", "S3 Transfer Acceleration", "S3 Intelligent-Tiering", "S3 Replication Time Control (RTC)"]', '["S3 Replication Time Control (RTC)"]', 'Replication Time Control is designed to replicate 99.99% of objects within 15 minutes and is backed by an SLA, with metrics to track it.', 4, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000052', '41000000-0000-0000-0000-000000000002', 'What is the minimum storage duration charge for S3 Standard-IA?', 'single_choice', '["90 days", "180 days", "30 days", "There is no minimum"]', '["30 days"]', 'Standard-IA charges for at least 30 days, even if the object is deleted sooner. It also has a retrieval fee per GB.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000053', '41000000-0000-0000-0000-000000000002', 'An object stored in S3 Glacier Flexible Retrieval is deleted after 20 days. How is storage charged?', 'single_choice', '["Nothing, because it was deleted early", "For the 90-day minimum storage duration", "For 20 days only", "For 180 days"]', '["For the 90-day minimum storage duration"]', 'Glacier Flexible Retrieval has a 90-day minimum, so early deletion is charged as if stored for 90 days. Glacier Deep Archive has a 180-day minimum.', 4, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000054', '41000000-0000-0000-0000-000000000002', 'How long does a standard retrieval from S3 Glacier Deep Archive usually take?', 'single_choice', '["Milliseconds", "1 to 5 minutes", "About 30 days", "Within 12 hours"]', '["Within 12 hours"]', 'Deep Archive is the cheapest class, with standard retrievals within 12 hours (bulk within 48 hours).', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000055', '41000000-0000-0000-0000-000000000002', 'Archived files are almost never read, but now and then one is needed within a few minutes. Which option is the best fit?', 'single_choice', '["S3 Glacier Deep Archive, using standard retrieval when a file is needed", "S3 One Zone-IA, moved by a lifecycle rule after 30 days", "S3 Glacier Flexible Retrieval, using expedited retrieval when needed", "S3 Glacier Deep Archive, using bulk retrieval when a file is needed"]', '["S3 Glacier Flexible Retrieval, using expedited retrieval when needed"]', 'Expedited retrievals from Glacier Flexible Retrieval usually return data in 1 to 5 minutes. Deep Archive retrievals take hours.', 4, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000056', '41000000-0000-0000-0000-000000000002', 'Which statement about S3 Intelligent-Tiering is correct?', 'single_choice', '["It charges a retrieval fee for every GB read from the infrequent tier.", "It is only suitable for objects smaller than 128 KB.", "It only moves objects between tiers if you also write lifecycle rules.", "It has no retrieval fees, but adds a small monitoring fee per object."]', '["It has no retrieval fees, but adds a small monitoring fee per object."]', 'Intelligent-Tiering moves objects between tiers automatically with no retrieval fees. Objects smaller than 128 KB are not monitored and stay in the frequent access tier.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000057', '41000000-0000-0000-0000-000000000002', 'Product images are read by users many times every day. Which storage class should store them?', 'single_choice', '["S3 Standard", "S3 Standard-IA", "S3 One Zone-IA", "S3 Glacier Instant Retrieval"]', '["S3 Standard"]', 'Frequently read data belongs in S3 Standard. Infrequent access classes add retrieval fees that would cost more for data read every day.', 1, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000058', '41000000-0000-0000-0000-000000000002', 'Which statement about encryption of new objects in S3 is correct?', 'single_choice', '["New objects must use AWS KMS keys.", "New objects are encrypted at rest with SSE-S3 by default.", "Only client-side encryption is supported.", "New objects are unencrypted unless you turn encryption on."]', '["New objects are encrypted at rest with SSE-S3 by default."]', 'Since January 2023, S3 applies SSE-S3 encryption to all new objects by default. You can choose SSE-KMS for more control.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000059', '41000000-0000-0000-0000-000000000002', 'A bucket with a very high request rate uses SSE-KMS, and AWS KMS request costs are high. What is the best way to reduce them?', 'single_choice', '["Turn on S3 Transfer Acceleration", "Turn on S3 Bucket Keys", "Turn on versioning", "Turn off encryption"]', '["Turn on S3 Bucket Keys"]', 'S3 Bucket Keys create a bucket-level key that reduces requests from S3 to KMS, which can lower KMS costs a lot while keeping SSE-KMS.', 4, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000060', '41000000-0000-0000-0000-000000000002', 'Data must be encrypted before it leaves the company''s own servers, so AWS never receives it unencrypted. What should the company use?', 'single_choice', '["Client-side encryption", "Block Public Access", "SSE-S3", "SSE-KMS"]', '["Client-side encryption"]', 'With client-side encryption, data is encrypted before upload. Server-side encryption happens after S3 receives the data.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000061', '41000000-0000-0000-0000-000000000002', 'An auditor needs a record of who deleted which objects in a bucket. What should you turn on?', 'single_choice', '["VPC Flow Logs for the subnets that use the bucket", "AWS Budgets alerts for the bucket", "AWS CloudTrail data events for Amazon S3", "S3 Intelligent-Tiering monitoring reports"]', '["AWS CloudTrail data events for Amazon S3"]', 'CloudTrail data events record object-level API calls such as DeleteObject, including who made them and when.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000062', '41000000-0000-0000-0000-000000000002', 'Users around the world upload large files to one bucket in eu-west-2, and uploads from far away are slow. What can improve upload speed?', 'single_choice', '["S3 Transfer Acceleration", "S3 Standard-IA", "Versioning", "S3 One Zone-IA"]', '["S3 Transfer Acceleration"]', 'Transfer Acceleration routes uploads through the nearest CloudFront edge location and then over the AWS network to the bucket.', 3, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000063', '41000000-0000-0000-0000-000000000002', 'When a new image is uploaded to a bucket, a thumbnail must be created automatically. What is the best design?', 'single_choice', '["A lifecycle rule that creates a thumbnail when each object is uploaded", "S3 Glacier Flexible Retrieval with expedited processing", "An S3 event notification that invokes an AWS Lambda function", "S3 Replication to a second bucket that resizes the images"]', '["An S3 event notification that invokes an AWS Lambda function"]', 'S3 event notifications can trigger Lambda when objects are created, which is the standard serverless way to process uploads.', 2, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000064', '41000000-0000-0000-0000-000000000002', 'A bucket must only be usable through one specific gateway VPC endpoint. How do you enforce this?', 'single_choice', '["A network ACL rule on the bucket that allows only the endpoint''s subnet", "A security group attached to the bucket that allows only the VPC CIDR", "Turning on Block Public Access, which limits access to the VPC automatically", "A bucket policy that denies requests unless aws:SourceVpce matches the endpoint ID"]', '["A bucket policy that denies requests unless aws:SourceVpce matches the endpoint ID"]', 'Buckets do not have security groups or network ACLs. A bucket policy condition on aws:SourceVpce limits access to requests that come through that endpoint.', 4, '60000000-0000-0000-0000-000000000001', 'published'),
    ('62000000-0000-0000-0003-000000000065', '41000000-0000-0000-0000-000000000002', 'Data is rarely read after 90 days. Which TWO options can lower its storage cost automatically? (Choose two.)', 'multiple_choice', '["Storing the objects in S3 Intelligent-Tiering", "Turning on S3 Transfer Acceleration for downloads of older data", "A lifecycle rule moving objects to Glacier Flexible Retrieval after 90 days", "Turning on Cross-Region Replication to a second bucket in S3 Standard", "Turning on versioning so older copies are kept in the same storage class"]', '["A lifecycle rule moving objects to Glacier Flexible Retrieval after 90 days", "Storing the objects in S3 Intelligent-Tiering"]', 'Lifecycle transitions and Intelligent-Tiering both move cold data to cheaper storage without manual work. Versioning and replication add storage, and Transfer Acceleration costs extra.', 3, '60000000-0000-0000-0000-000000000001', 'published')
